import React from 'react';

function DecorService() {
  return (
    <div className="container py-4">
      <h2 className="text-center text-success mb-4">Trang trí tiệc theo chủ đề</h2>
      <p>
        Biến mọi bữa tiệc thành không gian mơ ước với các gói trang trí cá nhân hóa, sáng tạo và độc đáo.
      </p>
      <ul>
        <li>Trang trí theo màu sắc hoặc concept riêng</li>
        <li>Backdrop handmade, ánh sáng nghệ thuật</li>
        <li>Decor sinh nhật, cưới hỏi, baby shower</li>
        <li>Có thể thi công tại nhà hoặc địa điểm thuê</li>
      </ul>
    </div>
  );
}

export default DecorService;
